import { StyleSheet, type StyleProp, type ViewStyle } from 'react-native';
import { GlassSurface } from './glass-surface';
import { NativePicker } from './lib/picker';

export type GlassPickerProps<T extends string = string> = {
  label: string;
  options: readonly { label: string; value: T }[];
  value: T;
  onValueChange: (value: T) => void;
  /** iOS supports an inline wheel; Android and web use their native dropdown. */
  appearance?: 'menu' | 'wheel';
  disabled?: boolean;
  style?: StyleProp<ViewStyle>;
  testID?: string;
};

/** A labelled system picker on glass: SwiftUI on iOS, Compose on Android, a select on web. */
export function GlassPicker<T extends string>({ style, ...props }: GlassPickerProps<T>) {
  if (!props.options.some((option) => option.value === props.value)) {
    throw new Error('GlassPicker value must match an option.');
  }

  return (
    <GlassSurface elevation="none" preset="control" style={[styles.surface, style]}>
      <NativePicker {...props} />
    </GlassSurface>
  );
}

const styles = StyleSheet.create({ surface: { padding: 12 } });

import { useEffect, useState } from 'react';
import { Host } from '@expo/ui';
import {
  DropdownMenuItem,
  ExposedDropdownMenu,
  ExposedDropdownMenuBox,
  Text,
  TextField,
  useNativeState,
} from '@expo/ui/jetpack-compose';
import { menuAnchor, semantics, testID as nativeTestID } from '@expo/ui/jetpack-compose/modifiers';
import type { GlassPickerProps } from '../glass-picker';
import { useGlassTheme } from '../glass-provider';

// Metro selects picker.ios and picker.web on those platforms. This is the Android implementation.
export function NativePicker<T extends string>({
  label,
  options,
  value,
  onValueChange,
  disabled = false,
  testID,
}: GlassPickerProps<T>) {
  const { preferences } = useGlassTheme();
  const [expanded, setExpanded] = useState(false);
  const selected = options.find((option) => option.value === value);
  const text = useNativeState(selected?.label ?? value);

  useEffect(() => {
    text.set(selected?.label ?? value);
  }, [selected?.label, text, value]);

  return (
    <Host
      colorScheme={preferences.theme}
      matchContents={{ vertical: true }}
      style={{ width: '100%' }}
    >
      <ExposedDropdownMenuBox
        expanded={expanded && !disabled}
        onExpandedChange={disabled ? undefined : setExpanded}
      >
        <TextField
          value={text}
          enabled={!disabled}
          readOnly
          modifiers={[
            menuAnchor('primaryNotEditable', !disabled),
            semantics({ contentDescription: label }),
            ...(testID ? [nativeTestID(testID)] : []),
          ]}
        >
          <TextField.Label>
            <Text>{label}</Text>
          </TextField.Label>
        </TextField>
        <ExposedDropdownMenu
          expanded={expanded && !disabled}
          onDismissRequest={() => setExpanded(false)}
        >
          {options.map((option) => (
            <DropdownMenuItem
              key={option.value}
              onClick={() => {
                setExpanded(false);
                onValueChange(option.value);
              }}
            >
              <DropdownMenuItem.Text>
                <Text>{option.label}</Text>
              </DropdownMenuItem.Text>
            </DropdownMenuItem>
          ))}
        </ExposedDropdownMenu>
      </ExposedDropdownMenuBox>
    </Host>
  );
}

import { Host } from '@expo/ui';
import { Picker, Text } from '@expo/ui/swift-ui';
import { disabled as nativeDisabled, pickerStyle, tag, tint } from '@expo/ui/swift-ui/modifiers';
import { Text as NativeText, View } from 'react-native';
import type { GlassPickerProps } from '../glass-picker';
import { useGlassTheme } from '../glass-provider';

export function NativePicker<T extends string>({
  label,
  options,
  value,
  onValueChange,
  appearance = 'menu',
  disabled = false,
  testID,
}: GlassPickerProps<T>) {
  const { colors, preferences } = useGlassTheme();
  const wheel = appearance === 'wheel';

  return (
    <View
      style={{
        alignItems: wheel ? 'stretch' : 'center',
        flexDirection: wheel ? 'column' : 'row',
        gap: 12,
        justifyContent: 'space-between',
        minHeight: 44,
      }}
    >
      <NativeText style={{ color: colors.foreground, fontSize: 16 }}>{label}</NativeText>
      <Host
        colorScheme={preferences.theme}
        matchContents={wheel ? { vertical: true } : { horizontal: true }}
        style={wheel ? { width: '100%' } : { height: 44 }}
      >
        <Picker
          label={label}
          selection={value}
          onSelectionChange={onValueChange}
          modifiers={[pickerStyle(appearance), nativeDisabled(disabled), tint(colors.accent)]}
          testID={testID}
        >
          {options.map((option) => (
            <Text key={option.value} modifiers={[tag(option.value)]}>
              {option.label}
            </Text>
          ))}
        </Picker>
      </Host>
    </View>
  );
}

import { useId } from 'react';
import type { GlassPickerProps } from '../glass-picker';
import { useGlassTheme } from '../glass-provider';

/** The browser's real select preserves labels, keyboard input, and native option menus. */
export function NativePicker<T extends string>({
  label,
  options,
  value,
  onValueChange,
  disabled = false,
  testID,
}: GlassPickerProps<T>) {
  const id = useId();
  const { colors, preferences } = useGlassTheme();

  return (
    <div
      style={{
        display: 'flex',
        position: 'relative',
        alignItems: 'center',
        gap: 12,
        justifyContent: 'space-between',
        fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
      }}
    >
      <label htmlFor={id} style={{ color: colors.foreground, fontSize: 16 }}>
        {label}
      </label>
      <select
        id={id}
        data-testid={testID}
        value={value}
        disabled={disabled}
        onChange={(event) => {
          const option = options.find((item) => item.value === event.target.value);

          if (option) onValueChange(option.value);
        }}
        style={{
          background: colors.opaqueSurface,
          color: colors.foreground,
          colorScheme: preferences.theme,
          border: `1px solid ${colors.border}`,
          borderRadius: 10,
          font: 'inherit',
          fontSize: 16,
          minHeight: 44,
          maxWidth: '65%',
          padding: '8px 12px',
        }}
      >
        {options.map((option) => (
          <option key={option.value} value={option.value}>
            {option.label}
          </option>
        ))}
      </select>
    </div>
  );
}
